def get_neighbors(r, c, grid, radius=1):
    neighbors = []
    for dr in range(-radius, radius+1):
        for dc in range(-radius, radius+1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r+dr, c+dc
            if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                neighbors.append((nr, nc))
    return neighbors

def chebyshev_to_2(r, c, grid):
    min_d = float('inf')
    for sr in range(grid.shape[0]):
        for sc in range(grid.shape[1]):
            if grid[sr,sc] == 2:
                d = max(abs(r-sr), abs(c-sc))
                min_d = min(min_d, d)
    return min_d

