        return 2

    if v == 0:
        return 0

    # 3 at distance <= 2 from a 2
    dist_to_2 = chebyshev_to_2(r, c, grid)

    if dist_to_2 <= 1:
        return 1

    if dist_to_2 == 2:
        # Check shielding: path to 2 goes through another 3?
        # Look at directions where there's a 3 at distance 1 from this cell that points toward the 2
