from collections import deque

def solve_3adj_and_dist(grid, width, height):
    """
    Rule:
    - 2s stay 2
    - 3s that have a 3-nearby (8-neighbor 3) stay 3
    - Isolated 3s (no 3-nearby) at Chebyshev distance <= 2 from a 2 become 1
    - Isolated 3s at distance > 2 from all 2s stay 3
    - 0s stay 0
    """
    out = np.copy(grid)

    # First: find all 3s that are 8-adjacent to another 3
    is_3_adj = np.zeros((height, width), dtype=bool)
    for r in range(height):
        for c in range(width):
            if grid[r,c] == 3:
                for dr in [-1,0,1]:
                    for dc in [-1,0,1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr,nc] == 3:
                                is_3_adj[r,c] = True
                                break
                    if is_3_adj[r,c]:
                        break

    # Second: for isolated 3s, check distance to nearest 2
    def chebyshev_to_nearest_2(r, c):
        best = float('inf')
        for sr in range(height):
            for sc in range(width):
                if grid[sr,sc] == 2:
                    d = max(abs(r-sr), abs(c-sc))
                    best = min(best, d)
        return best

    for r in range(height):
        for c in range(width):
            if grid[r,c] == 3 and not is_3_adj[r,c]:
                d_to_2 = chebyshev_to_nearest_2(r, c)
                if d_to_2 <= 2:
                    out[r,c] = 1
                else:
                    out[r,c] = 3

    return out

